<?php
require __DIR__.'/layout.php'; require_login(); if((current_user()['role']??'')!=='admin'){http_response_code(403);exit('Acesso restrito ao administrador.');}
$msg='';$err='';try{if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$name=trim($_POST['name']??'');$email=strtolower(trim($_POST['email']??''));$pass=$_POST['password']??'';$role=in_array($_POST['role']??'', ['admin','financeiro','consulta'],true)?$_POST['role']:'consulta';if(!$name||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($pass)<8)throw new RuntimeException('Preencha nome, e-mail e senha com mínimo de 8 caracteres.');$s=$pdo->prepare('INSERT INTO users(name,email,password_hash,role) VALUES(?,?,?,?)');$s->execute([$name,$email,password_hash($pass,PASSWORD_DEFAULT),$role]);audit('criou usuário',$email.' - '.$role);$msg='Usuário criado.';}}catch(Throwable $e){$err=$e->getMessage();}$users=$pdo->query('SELECT id,name,email,role,active,last_login,created_at FROM users ORDER BY name')->fetchAll();page_top('Usuários');?><?php if($msg):?><div class="flash"><?=h($msg)?></div><?php endif;if($err):?><div class="error"><?=h($err)?></div><?php endif;?><div class="grid g2"><section class="card"><h2>Novo usuário</h2><form method="post"><?=csrf_field()?><label>Nome</label><input name="name" required><label>E-mail</label><input type="email" name="email" required><label>Senha inicial</label><input type="password" name="password" required><label>Perfil</label><select name="role"><option value="financeiro">Financeiro - lança e edita</option><option value="consulta">Consulta - somente leitura</option><option value="admin">Administrador</option></select><div class="actions"><button>Criar usuário</button></div></form></section><section class="card"><h2>Perfis de acesso</h2><p><b>Administrador:</b> acesso total e criação de usuários.</p><p><b>Financeiro:</b> cadastra prestações, notas, entradas, saídas e comprovantes.</p><p><b>Consulta:</b> visualiza dados e relatórios sem alterar lançamentos.</p></section></div><div class="section-title"><h2>Usuários cadastrados</h2></div><div class="tablewrap"><table><thead><tr><th>Nome</th><th>E-mail</th><th>Perfil</th><th>Ativo</th><th>Último acesso</th></tr></thead><tbody><?php foreach($users as $u):?><tr><td><?=h($u['name'])?></td><td><?=h($u['email'])?></td><td><?=h($u['role'])?></td><td><?=$u['active']?'Sim':'Não'?></td><td><?=h($u['last_login']?:'—')?></td></tr><?php endforeach;?></tbody></table></div><?php page_bottom();?>
